package com.metabuild.modules.admin.dictionaries.controller;
import com.metabuild.admin.api.security.RequiresPermissions;import com.metabuild.modules.admin.dictionaries.application.*;import com.metabuild.shared.kernel.BadRequest;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/dictionaries") public final class DictionaryController {private final DictionaryService service;public DictionaryController(DictionaryService service){this.service=service;}@GetMapping @RequiresPermissions(codes={"sys:dict:view"}) public List<DictionaryView> list(){return service.list();}@PostMapping @RequiresPermissions(codes={"sys:dict:create"}) public DictionaryView create(@RequestBody DictionaryWrite x){body(x);return service.create(x.name(),x.code(),x.remark(),x.builtin());}@PutMapping("/{id}") @RequiresPermissions(codes={"sys:dict:update"}) public DictionaryView update(@PathVariable UUID id,@RequestBody DictionaryUpdate x){body(x);return service.update(id,x.name(),x.remark());}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) @RequiresPermissions(codes={"sys:dict:delete"}) public void delete(@PathVariable UUID id){service.delete(id);}@GetMapping("/{id}/items") @RequiresPermissions(codes={"sys:dict:view"}) public List<DictionaryItemView> items(@PathVariable UUID id){return service.items(id);}@PostMapping("/{id}/items") @RequiresPermissions(codes={"sys:dict:create"}) public DictionaryItemView createItem(@PathVariable UUID id,@RequestBody ItemWrite x){body(x);return service.createItem(id,x.label(),x.value(),x.sort(),x.enabled(),x.color(),x.remark());}@PutMapping("/{dictionaryId}/items/{itemId}") @RequiresPermissions(codes={"sys:dict:update"}) public DictionaryItemView updateItem(@PathVariable UUID dictionaryId,@PathVariable UUID itemId,@RequestBody ItemWrite x){body(x);return service.updateItem(dictionaryId,itemId,x.label(),x.value(),x.sort(),x.enabled(),x.color(),x.remark());}@PatchMapping("/{dictionaryId}/items/{itemId}/enabled") @RequiresPermissions(codes={"sys:dict:update"}) public DictionaryItemView enabled(@PathVariable UUID dictionaryId,@PathVariable UUID itemId,@RequestBody Enabled x){body(x);return service.setItemEnabled(dictionaryId,itemId,x.enabled());}@DeleteMapping("/{dictionaryId}/items/{itemId}") @ResponseStatus(HttpStatus.NO_CONTENT) @RequiresPermissions(codes={"sys:dict:delete"}) public void deleteItem(@PathVariable UUID dictionaryId,@PathVariable UUID itemId){service.deleteItem(dictionaryId,itemId);}public record DictionaryWrite(String name,String code,String remark,boolean builtin){}public record DictionaryUpdate(String name,String remark){}public record ItemWrite(String label,String value,int sort,boolean enabled,String color,String remark){}public record Enabled(boolean enabled){}private static void body(Object x){if(x==null)throw new BadRequest(()->"request.validation.failed","Request body is required");}}
